def compute(vars):
    values = {
        "year ended June 30, 2019": vars["v1"],
        "year ended June 24, 2018": vars["v2"],
        "year ended June 25, 2017": vars["v3"],
    }
    highest_year = max(values, key=values.get)
    return {
        "value": highest_year,
        "trace": {
            "values_by_year": values,
            "highest_value": values[highest_year],
            "output_meta": {"currency": None, "scale": None, "unit": "year"},
        },
    }
